INSERT INTO registry_changes (id, entity, entity_code, change, rationale, effective_on, version) VALUES
(1, 'sector', 'CST', 'Skills Framework for Carbon Services and Trading published', 'New sector framework covering carbon measurement, project development and trading.', '2024-05-01', '1.0'),
(2, 'sector', 'CST', 'Revision 1.1: nature-based solutions and climate risk skills added', 'Employer consultation identified two capability gaps in the original framework.', '2025-11-01', '1.1'),
(3, 'tsc', 'ICT-009', 'New TSC: Applied AI and Generative Systems', 'Added across the Infocomm Technology framework following demand signals from industry.', '2025-06-01', '4.2'),
(4, 'tsc', 'X-SWP-003', 'New cross-sector TSC: Artificial Intelligence Application', 'Recognised as cross-sector after appearing in 18 sector frameworks.', '2025-06-01', '4.2'),
(5, 'ccs', 'CCS-DIG', 'Digital Fluency descriptors revised at Intermediate and Advanced', 'Aligned with the expectation that most roles now automate part of their own work.', '2025-01-15', '2.3'),
(6, 'role', 'HRE-R07', 'New role: Job Redesign Consultant', 'Added to the Human Resource framework to support skills-first job redesign.', '2025-04-01', '3.1'),
(7, 'sector', 'HLT', 'Revision: community and home care skills expanded', 'Care model shift towards ageing-in-place.', '2025-03-01', '5.0'),
(8, 'funding', 'SFTA-PT', 'Mid-Career Training Allowance extended to selected part-time training', 'Allows mid-career workers to train without leaving employment.', '2026-03-01', '1.0'),
(9, 'agency', 'SWDA', 'Registry stewardship transferred to the Skills and Workforce Development Agency', 'SkillsFuture Singapore and Workforce Singapore merged into SWDA on 1 July 2026.', '2026-07-01', '1.0');
